using System;using System.IO;using System.Linq;using FUI.Binding;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using NUnit.Framework;
namespace FUI.Portable.Tests{public sealed class ITextMigrationTests{
const string OldImplementation="using FUI.Binding;using FUI.Rendering;namespace TextMigration{public sealed class OldText:ITextElement{public string Name=>\"Old\";public IElement Parent=>null;public BindableProperty<string> Text{get;}=new BindableProperty<string>(\"\");}}";
static CSharpCompilation Compile(params string[] sources){var paths=((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")).Split(Path.PathSeparator).Where(p=>!Path.GetFileName(p).StartsWith("FUI."));var refs=paths.Concat(new[]{typeof(ObservableObject).Assembly.Location}).Distinct().Select(p=>MetadataReference.CreateFromFile(p));return CSharpCompilation.Create("TextMigrationContract",sources.Select(s=>CSharpSyntaxTree.ParseText(s)),refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));}
static string Fixture(string name)=>File.ReadAllText(Path.Combine(TestContext.CurrentContext.TestDirectory,"Tests",name));
[Test]public void OldCustomTextImplementationCompilesAgainstActualOldDeclaration(){var old=Compile(Fixture("LegacyITextContract.cs.txt"),OldImplementation);Assert.That(old.GetDiagnostics().Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);}
[Test]public void NewITextExplicitlyRequiresAllSixAddedMembersFromOldCustomBackend(){var errors=Compile(OldImplementation).GetDiagnostics().Where(d=>d.Severity==DiagnosticSeverity.Error).ToArray();Assert.That(errors.Length,Is.EqualTo(6));Assert.That(errors.All(d=>d.Id=="CS0535"),Is.True);foreach(var member in new[]{"FontSize","RichText","Visible","Tint","TextAlignment","FormattedTextValue"}){Assert.That(errors.Any(d=>d.GetMessage().Contains("."+member)),Is.True,member);}}
[Test]public void MigratedCustomBackendCompilesAgainstRealCoreAndSharesGraphicalState(){var a=GeneratedCompilation.Compile(("ITextCustomMigration.cs",Fixture("ITextCustomMigration.cs.txt")));Assert.That((string[])a.GetType("TextMigration.Scenario").GetMethod("Run").Invoke(null,null),Is.EqualTo(new[]{"True","1","30"}));}
}}
